  "eslint.config.mjs": "// Generated by bildr. Editing this file detaches it from the editor.\n// @ts-check\nimport withNuxt from './.nuxt/eslint.config.mjs'\n\n// Clean architecture boundaries: dependencies point inward only (domain <- application <- infrastructure/http <- presentation).\nconst banned = {\n  vue: { group: ['vue', 'vue-router', '#app', '#imports', '@tanstack/*'], message: 'Only the presentation ring (app/) may use Vue or the client data layer.' },\n  server: { group: ['nuxt/server', 'nitropack', 'nitropack/*', 'h3', 'drizzle-orm', 'drizzle-orm/*', '@libsql/*'], message: 'Only server/infrastructure, server/api and composition roots may use Nitro or the database.' },\n  serverDirs: { group: ['**/server/**', '../server/*'], message: 'The client must not import server code; call the API through the module composables.' },\n  infrastructure: { group: ['**/infrastructure/**', '../infrastructure/*'], message: 'Use-cases depend on ports, not adapters.' },\n  appDirs: { group: ['**/app/**'], message: 'Server and shared code must not import the app.' }\n}\n\nexport default withNuxt(\n  { files: ['layers/*/shared/**/*.ts'], rules: { 'no-restricted-imports': ['error', { patterns: [banned.vue, banned.server, banned.serverDirs, banned.appDirs] }] } },\n  // The rings an API source keeps under shared/ (it runs on the server or in the page): its domain and use-cases don't see its adapters.\n  { files: ['layers/*/shared/domain/**/*.ts', 'layers/*/shared/application/**/*.ts'], rules: { 'no-restricted-imports': ['error', { patterns: [banned.vue, banned.server, banned.serverDirs, banned.appDirs, banned.infrastructure] }] } },\n  { files: ['layers/*/server/application/**/*.ts'], rules: { 'no-restricted-imports': ['error', { patterns: [banned.vue, banned.server, banned.infrastructure, banned.appDirs] }] } },\n  { files: ['layers/*/server/api/**/*.ts'], rules: { 'no-restricted-imports': ['error', { patterns: [banned.vue, banned.infrastructure, banned.appDirs] }] } },\n  { files: ['layers/*/server/infrastructure/**/*.ts'], rules: { 'no-restricted-imports': ['error', { patterns: [banned.vue, banned.appDirs] }] } },\n  { files: ['layers/*/app/**/*.{ts,vue}'], rules: { 'no-restricted-imports': ['error', { patterns: [banned.server, banned.serverDirs] }] } }\n)\n",
